"""Client addresses (docs/ratelimit.md, section 7)."""

import ipaddress
import re

_V4 = re.compile(r"([0-9.]+)(?::[0-9]+)?")
_V6B = re.compile(r"\[([0-9A-Fa-f:.]+)\](?::[0-9]+)?")


def _norm(a):
    if a.version == 6 and a.ipv4_mapped is not None:
        return a.ipv4_mapped
    return a


def parse_address(text):
    """An ipaddress object (IPv4-mapped normalised to IPv4), or None when text is not an address."""
    if not isinstance(text, str):
        return None
    try:
        m = _V6B.fullmatch(text)
        if m:
            return _norm(ipaddress.IPv6Address(m.group(1)))
        if ":" in text and "." not in text.split(":")[0] and _V4.fullmatch(text) is None:
            return _norm(ipaddress.IPv6Address(text))
        m = _V4.fullmatch(text)
        if m:
            return ipaddress.IPv4Address(m.group(1))
        if ":" in text:
            return _norm(ipaddress.IPv6Address(text))
    except ValueError:
        return None
    return None


def in_any(addr, nets) -> bool:
    return any(addr.version == n.version and addr in n for n in nets)


def client_address(request, trusted):
    """The client address of a request as an ipaddress object, or None."""
    peer = parse_address(request.peer)
    if peer is None or not in_any(peer, trusted):
        return peer
    entries = []
    for value in request.headers.get_all("X-Forwarded-For"):
        entries.extend(e.strip(" \t") for e in value.split(","))
    if not entries:
        return peer
    result = peer
    for e in reversed(entries):
        a = parse_address(e)
        if a is None:
            return result
        if not in_any(a, trusted):
            return a
        result = a
    return result


def key_text(addr) -> str:
    if addr.version == 4:
        return str(addr)
    return str(ipaddress.ip_network((addr, 64), strict=False))
