"""Stage 3: rate limiting (docs/ratelimit.md)."""

import math
from fractions import Fraction

from frontdoor.ratelimit.addresses import client_address, in_any, key_text
from frontdoor.ratelimit.state import new_state

NAME = "ratelimit"
INF = math.inf


class State:
    def __init__(self, config):
        self.limits = config.section("limit") or []
        self.trusted = config.section("clients") or ()
        self.buckets = {}
        self.now = None
        self.limited = {l.name: 0 for l in self.limits}


def setup(config):
    return State(config)


def _key(limit, ctx, client):
    vals = []
    for part in limit.key:
        if part == "tenant":
            v = ctx.tenant
        elif part == "client":
            v = key_text(client) if client is not None else None
        elif part == "route":
            v = ctx.route.name
        elif part == "method":
            v = ctx.request.method.upper()
        else:
            raw = ctx.request.headers.get(part[len("header:"):])
            v = raw.strip(" \t") if raw is not None else None
            if v == "":
                v = None
        if v is None:
            return None
        vals.append(v)
    return tuple(vals)


def handle(ctx, st):
    if not st.limits:
        return None
    req = ctx.request
    st.now = req.ts_ms if st.now is None else max(st.now, req.ts_ms)
    now = st.now
    method = req.method.upper()
    client = client_address(req, st.trusted)
    covering = []
    for limit in st.limits:
        if limit.routes is not None and ctx.route.name not in limit.routes:
            continue
        if limit.methods is not None and method not in limit.methods:
            continue
        key = _key(limit, ctx, client)
        if key is None:
            continue
        if client is not None and in_any(client, limit.exempt):
            continue
        slot = (limit.name, key)
        s = st.buckets.get(slot)
        if s is None:
            s = st.buckets[slot] = new_state(limit, now)
        s.refill(now)
        covering.append((limit, s, limit.cost_of(method)))
    if not covering:
        return None
    refusing = [(l, s, c) for l, s, c in covering if c > l.capacity or not s.allows(c)]
    if not refusing:
        for l, s, c in covering:
            s.charge(c)
        limit, s, c = min(covering, key=lambda x: x[1].remaining())  # min is stable: first on ties
        status = None
    else:
        def wait(x):
            l, s, c = x
            return INF if c > l.capacity else s.wait(c, now)
        best = None
        for x in refusing:
            if best is None or wait(x) > wait(best):
                best = x
        limit, s, c = best
        for l, _, _ in refusing:
            st.limited[l.name] += 1
        status = 429
    ctx.headers["RateLimit-Limit"] = str(limit.capacity)
    ctx.headers["RateLimit-Remaining"] = str(s.remaining())
    ctx.headers["RateLimit-Reset"] = str(s.reset(now))
    if status == 429:
        w = wait(best)
        if w != INF:
            ctx.headers["Retry-After"] = str(max(1, math.ceil(Fraction(w) / 1000)))
    return status


def summary(st):
    if not st.limits:
        return {}
    return {"limited": dict(st.limited)}
